/**
 * Commands are the ONLY way to change a ScoreDoc.
 *
 * - Plain JSON: they can be logged, sent over the network (collaboration), replayed (history),
 *   produced by AI (Cantelvio patches) and stored in version history.
 * - Deterministic: ids of new elements are part of the payload (generated by the caller), so
 *   applying the same command to the same document always produces the same result.
 * - Validated: a command that cannot apply throws CommandError and changes nothing.
 */
import type { ClefType } from '../model/clef';
import type {
  Arpeggio,
  Articulation,
  BarlineStyle,
  Breath,
  ChordSymbol,
  DynamicMark,
  GraceNote,
  ID,
  MeasureAnchor,
  NoteEvent,
  Ornament,
  Part,
  ScoreMeta,
  ScorePosition,
  ScoreSettings,
  Spanner,
  TempoMark,
} from '../model/types';
import type { KeySignature, Pitch } from '../pitch/pitch';
import type { TimeSignature } from '../time/meter';
import type { Rational } from '../time/rational';

/** Event marks set by `events.setProps`: a value sets the mark, null (or cue: false) removes it. */
export interface EventProps {
  readonly ornament?: Ornament | null;
  readonly tremolo?: number | null;
  readonly arpeggio?: Arpeggio | null;
  readonly cue?: boolean;
  readonly breath?: Breath | null;
}

export type Command =
  // ---- document
  | { readonly type: 'meta.set'; readonly patch: Partial<ScoreMeta> }
  | { readonly type: 'settings.set'; readonly patch: Partial<ScoreSettings> }
  // ---- measures
  | { readonly type: 'measures.insert'; readonly index: number; readonly ids: readonly ID[] }
  | { readonly type: 'measures.delete'; readonly measureIds: readonly ID[] }
  | {
      readonly type: 'measure.setTimeSig';
      readonly measureId: ID;
      readonly timeSig: TimeSignature;
      readonly newMeasureIds: readonly ID[];
    }
  | { readonly type: 'measure.setKeySig'; readonly measureId: ID; readonly keySig: KeySignature }
  | { readonly type: 'measure.setBarline'; readonly measureId: ID; readonly barline: BarlineStyle }
  | {
      readonly type: 'measure.setRepeat';
      readonly measureId: ID;
      readonly start?: boolean;
      readonly end?: boolean;
    }
  | { readonly type: 'measure.setTempo'; readonly measureId: ID; readonly tempo: TempoMark | null }
  | {
      readonly type: 'measure.setBreak';
      readonly measureId: ID;
      readonly breakAfter: 'system' | 'page' | null;
    }
  | {
      readonly type: 'measure.setRehearsalMark';
      readonly measureId: ID;
      readonly text: string | null;
    }
  // ---- notes & rests
  | {
      readonly type: 'note.enter';
      readonly at: ScorePosition;
      /** Actual (sounding) duration in whole notes. */
      readonly duration: Rational;
      readonly pitches: readonly Pitch[];
      readonly eventId: ID;
      readonly noteIds: readonly ID[];
      /** Tie the notes of the event that ends at `at` into this one (same pitches only). */
      readonly tieFromPrevious?: boolean;
    }
  | { readonly type: 'rest.enter'; readonly at: ScorePosition; readonly duration: Rational }
  /** Insert complete events verbatim (imports, AI results, paste). Fails on overlaps. */
  | {
      readonly type: 'events.insert';
      readonly staffId: ID;
      readonly measureId: ID;
      readonly voice: number;
      readonly events: readonly NoteEvent[];
    }
  | {
      readonly type: 'note.addToChord';
      readonly eventId: ID;
      readonly pitch: Pitch;
      readonly noteId: ID;
    }
  | { readonly type: 'note.setPitch'; readonly noteId: ID; readonly pitch: Pitch }
  | { readonly type: 'notes.delete'; readonly noteIds: readonly ID[] }
  | { readonly type: 'events.delete'; readonly eventIds: readonly ID[] }
  | { readonly type: 'event.setDuration'; readonly eventId: ID; readonly duration: Rational }
  | { readonly type: 'notes.setTie'; readonly noteIds: readonly ID[]; readonly tie: boolean }
  | {
      readonly type: 'events.setArticulation';
      readonly eventIds: readonly ID[];
      readonly articulation: Articulation;
      readonly on: boolean;
    }
  | {
      readonly type: 'events.setStem';
      readonly eventIds: readonly ID[];
      readonly stem: 'up' | 'down' | null;
    }
  | {
      readonly type: 'events.setProps';
      readonly eventIds: readonly ID[];
      readonly props: EventProps;
    }
  /**
   * Add a grace note before an event. `index` is its place among the event's grace notes in
   * playing order (0 = first; the number of graces = right before the principal note). Grace
   * notes are removed with `notes.delete` and re-pitched with `note.setPitch` like other notes.
   */
  | {
      readonly type: 'grace.add';
      readonly eventId: ID;
      readonly index: number;
      readonly grace: GraceNote;
    }
  /** Replace the grace note with the same id, in place (its value, slash or notes). */
  | { readonly type: 'grace.set'; readonly grace: GraceNote }
  | {
      readonly type: 'range.clear';
      readonly staffIds: readonly ID[];
      readonly from: MeasureAnchor;
      readonly to: MeasureAnchor;
      readonly voices?: readonly number[];
    }
  | {
      readonly type: 'tuplet.create';
      readonly at: ScorePosition;
      readonly length: Rational;
      readonly actual: number;
      readonly normal: number;
      readonly id: ID;
    }
  // ---- staff items
  | {
      readonly type: 'clef.set';
      readonly staffId: ID;
      readonly measureId: ID;
      readonly offset: Rational;
      readonly clef: ClefType;
      readonly id: ID;
    }
  | {
      readonly type: 'dynamic.set';
      readonly staffId: ID;
      readonly measureId: ID;
      readonly mark: DynamicMark;
    }
  | { readonly type: 'dynamic.delete'; readonly ids: readonly ID[] }
  // ---- spanners (slurs and lines)
  /** Add a spanner. Octave lines may not overlap another octave line of the staff. */
  | { readonly type: 'spanner.add'; readonly spanner: Spanner }
  /** Replace the spanner with the same id (e.g. extend a line while entering notes). */
  | { readonly type: 'spanner.set'; readonly spanner: Spanner }
  | { readonly type: 'spanners.delete'; readonly ids: readonly ID[] }
  // ---- harmony
  | { readonly type: 'harmony.set'; readonly chord: ChordSymbol }
  | { readonly type: 'harmony.delete'; readonly ids: readonly ID[] }
  // ---- parts
  | {
      readonly type: 'part.add';
      readonly index: number;
      readonly part: Part;
      readonly braceId?: ID;
    }
  | { readonly type: 'part.remove'; readonly partId: ID }
  | {
      readonly type: 'part.rename';
      readonly partId: ID;
      readonly name: string;
      readonly abbreviation: string;
    }
  // ---- provenance (AI suggestions)
  /** Mark everything produced by an AI run as accepted (drawn normally, exported as material). */
  | { readonly type: 'provenance.accept'; readonly runId: string }
  /** Remove the not-yet-accepted output of an AI run. */
  | { readonly type: 'provenance.reject'; readonly runId: string }
  // ---- composition
  | { readonly type: 'batch'; readonly label?: string; readonly commands: readonly Command[] };

export type CommandType = Command['type'];

export class CommandError extends Error {
  constructor(
    readonly command: Command,
    message: string,
  ) {
    super(`${command.type}: ${message}`);
    this.name = 'CommandError';
  }
}
